package config

import (
	"bytes"
	"encoding"
	"encoding/json"
	"fmt"
	"reflect"
	"slices"
	"strings"
	"testing"
	"time"
)

// This file generates config.schema.json (ADR 0007 decision 1). It lives in
// a _test.go file so the binary carries only the generated bytes.

// jsonObj is one JSON Schema object; encoding/json sorts its keys, so the
// output is deterministic.
type jsonObj = map[string]any

// Grammars of the text types, mirroring their parsers in types.go.
const (
	// ParseDuration: Go duration syntax, never negative.
	durationPattern = `^\s*\+?(0|(([0-9]+(\.[0-9]*)?|\.[0-9]+)(ns|us|µs|μs|ms|s|m|h))+)\s*$`
	// VideoSecond.UnmarshalText: auto (any case) or a decimal number.
	videoSecondPattern = `^\s*([Aa][Uu][Tt][Oo]|[-+]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][-+]?[0-9]+)?)\s*$`
	// ParseByteSize: an integer with an optional binary suffix, any case.
	byteSizePattern = `^\s*[0-9]+ *([KkMmGgTt][Ii][Bb]|[Bb])?\s*$`
	// HexKey.UnmarshalText: hex, whole bytes.
	hexKeyPattern = `^\s*([0-9a-fA-F]{2})+\s*$`
	// appendIntItem: a number, a range or a stepped range.
	intItemPattern = `\s*[0-9]+\s*(-\s*[0-9]+\s*(/\s*[0-9]+\s*)?)?`
	// validName: a source name.
	sourceNamePattern = `^[a-z0-9][a-z0-9-]*$`
	// Validate: a preset name has no ':' or '/'.
	presetNamePattern = `^[^:/]+$`
)

// schemaGen builds the schema from Config (fieldsOf) and CONFIG.md §2.
type schemaGen struct {
	docs []docVar
	// env maps a YAML path to its field from the walker; sources use the
	// literal name <name>.
	env map[string]field
}

func newSchemaGen(t *testing.T) *schemaGen {
	t.Helper()
	g := &schemaGen{docs: parseDocVars(t), env: map[string]field{}}
	for _, f := range append(staticFields(), sourceFields("<name>")...) {
		g.env[f.YAML] = f
	}
	return g
}

// generateSchema returns the indented schema document.
func generateSchema(t *testing.T) []byte {
	t.Helper()
	g := newSchemaGen(t)
	root := g.object(reflect.TypeFor[Config](), "", reflect.ValueOf(Defaults()))
	props, ok := root["properties"].(jsonObj)
	if !ok {
		t.Fatal("root schema has no properties")
	}
	props["$schema"] = jsonObj{
		"type":        "string",
		"description": "URL of this JSON Schema, for editors; the loader ignores it.",
	}
	root["$schema"] = "https://json-schema.org/draft/2020-12/schema"
	root["$id"] = SchemaID
	root["title"] = "xtandard-image configuration"
	root["description"] = "Config file of xtandard-image (YAML, JSON or TOML). Every key maps to an XI_* " +
		"environment variable, which wins over the file. See docs/CONFIG.md."
	root["$defs"] = g.defs()

	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(root); err != nil {
		t.Fatalf("encode schema: %v", err)
	}
	return buf.Bytes()
}

// defs are the shared definitions referenced with #/$defs/….
func (g *schemaGen) defs() jsonObj {
	d := jsonObj{
		"duration": jsonObj{
			"type":        "string",
			"pattern":     durationPattern,
			"description": "Go duration (5s, 1m30s, 24h); negative values are rejected.",
			"examples":    []string{"5s", "1m30s", "24h"},
		},
		"byteSize": jsonObj{
			"description": "Size in bytes: an integer, or a string with a binary suffix B, KiB, MiB, GiB or TiB (decimal MB is rejected).",
			"oneOf": []any{
				jsonObj{"type": "integer", "minimum": 0},
				jsonObj{"type": "string", "pattern": byteSizePattern},
			},
			"examples": []any{"10MiB", "512KiB", 1048576},
		},
		"intList": jsonObj{
			"description": "Integers: a string of comma-separated items, each a number, a range a-b or a stepped range a-b/step (5-100/5), or a list of such items.",
			"oneOf": []any{
				jsonObj{"type": "string", "pattern": "^" + intItemPattern + "(," + intItemPattern + ")*$"},
				jsonObj{"type": "array", "items": jsonObj{"oneOf": []any{
					jsonObj{"type": "integer", "minimum": 0},
					jsonObj{"type": "string", "pattern": "^" + intItemPattern + "$"},
				}}},
			},
			"examples": []any{"640-1080/220", []int{16, 32, 64}},
		},
		"videoSecond": jsonObj{
			"description": "A timestamp in seconds (negative counts from the end of the video), or auto for best-frame selection.",
			"oneOf":       []any{jsonObj{"type": "number"}, jsonObj{"type": "string", "pattern": videoSecondPattern}},
			"examples":    []any{"auto", 1, -2.5},
		},
		"tristate": jsonObj{
			"description": "true, false, or auto (derived from other settings).",
			"oneOf":       []any{jsonObj{"type": "boolean"}, jsonObj{"const": "auto"}},
		},
		"cidr": jsonObj{
			"type":        "string",
			"description": "A network in CIDR notation or a single address; host bits must be zero.",
			"examples":    []string{"10.0.0.0/8", "fd00::1"},
		},
		"fileRef": jsonObj{
			"type":                 "object",
			"description":          "Reads the value from a file (like XI_…_FILE): at most 64 KiB, trailing newline trimmed.",
			"additionalProperties": false,
			"required":             []string{"file"},
			"properties": jsonObj{
				"file": jsonObj{"type": "string", "pattern": "^/", "description": "Absolute path of the file holding the value."},
			},
		},
		"secret": jsonObj{
			"description": "A secret: a literal string or {file: /absolute/path}. Printed as [REDACTED].",
			"writeOnly":   true,
			"oneOf":       []any{jsonObj{"type": "string"}, jsonObj{"$ref": "#/$defs/fileRef"}},
		},
		"hexKey": jsonObj{
			"description": "Hex-encoded key material, or {file: /absolute/path} holding it. Printed as [REDACTED].",
			"writeOnly":   true,
			"oneOf": []any{
				jsonObj{"type": "string", "pattern": hexKeyPattern},
				jsonObj{"$ref": "#/$defs/fileRef"},
			},
		},
		"mount": g.mountDef(),
	}
	branches := make([]any, 0, len(sourceTypes()))
	for _, st := range sourceTypes() {
		name := "source_" + string(st)
		d[name] = g.sourceDef(st)
		branches = append(branches, jsonObj{"$ref": "#/$defs/" + name})
	}
	d["source"] = jsonObj{
		"description": "A named source; the fields that apply depend on type.",
		"type":        "object",
		"required":    []string{"type"},
		"oneOf":       branches,
	}
	return d
}

// sourceDef is the closed schema of a source of type st.
func (g *schemaGen) sourceDef(st SourceType) jsonObj {
	applies := sourceFieldTypes()
	s := g.object(reflect.TypeFor[Source](), "sources.<name>", reflect.Value{})
	props, _ := s["properties"].(jsonObj)
	for name := range props {
		if name != "type" && !slices.Contains(applies[name], st) {
			delete(props, name)
		}
	}
	typ, _ := props["type"].(jsonObj)
	delete(typ, "enum")
	delete(typ, "type")
	typ["const"] = string(st)
	s["required"] = []string{"type"}
	s["title"] = string(st) + " source"
	return s
}

// mountDef is one extra mount (dialects.<name>.mounts[]); YAML only.
func (g *schemaGen) mountDef() jsonObj {
	s := g.object(reflect.TypeFor[MountOptions](), "dialects.<name>", reflect.Value{})
	s["description"] = "An extra mount of the dialect (file only; no environment variable)."
	return s
}

// object is the closed schema of struct t at YAML path, with defaults from
// def when it is valid.
func (g *schemaGen) object(t reflect.Type, path string, def reflect.Value) jsonObj {
	props := jsonObj{}
	g.addFields(props, t, path, def)
	return jsonObj{"type": "object", "additionalProperties": false, "properties": props}
}

func (g *schemaGen) addFields(props jsonObj, t reflect.Type, path string, def reflect.Value) {
	for i := range t.NumField() {
		sf := t.Field(i)
		if !sf.IsExported() {
			continue
		}
		name, opts, _ := strings.Cut(sf.Tag.Get("yaml"), ",")
		var fdef reflect.Value
		if def.IsValid() {
			fdef = def.Field(i)
		}
		if opts == "inline" {
			g.addFields(props, sf.Type, path, fdef)
			continue
		}
		props[name] = g.property(sf.Type, joinPath(path, name), fdef)
	}
}

// property is the schema of one key: its type plus title, description and
// default.
func (g *schemaGen) property(t reflect.Type, path string, def reflect.Value) jsonObj {
	s := g.typeSchema(t, path, def)
	var desc []string
	literalDefault := true
	if f, ok := g.env[path]; ok {
		if d, ok := g.doc(f.Env); ok {
			desc = append(desc, d.describe()...)
			literalDefault = d.hasDef
		}
		env := "Env: `" + f.Env + "`"
		if containsSecret(t) {
			env += " (or `" + f.Env + fileSuffix + "`)"
		}
		desc = append(desc, env)
		s["title"] = f.Env
	} else if rest, ok := strings.CutPrefix(path, "dialects.<name>."); ok {
		if d, ok := g.doc("XI_DIALECTS_<NAME>_" + strings.ToUpper(rest)); ok {
			desc = append(desc, d.describe()...)
		}
	} else if strings.HasSuffix(path, ".mounts") {
		desc = append(desc, "Extra mounts of this dialect, each with its own prefix or hosts (file only; no environment variable).")
	}
	if len(desc) > 0 {
		md := strings.Join(desc, "\n\n")
		s["markdownDescription"] = md
		s["description"] = strings.ReplaceAll(md, "`", "")
	}
	// A formula default ("request timeout + 5s") is resolved by Load from
	// a zero value; the description states it instead.
	if def.IsValid() && literalDefault && !containsSecret(t) {
		if v, ok := defaultValue(def); ok {
			s["default"] = v
		}
	}
	return s
}

// doc returns the CONFIG.md §2 row documenting env, preferring an exact row
// over a <NAME>/<FMT> pattern.
func (g *schemaGen) doc(env string) (docVar, bool) {
	i := slices.IndexFunc(g.docs, func(d docVar) bool { return d.name == env })
	if i < 0 {
		i = slices.IndexFunc(g.docs, func(d docVar) bool { return d.matches(env) })
	}
	if i < 0 {
		return docVar{}, false
	}
	return g.docs[i], true
}

// describe is the row's Meaning plus its Default when that is a formula
// rather than a literal.
func (d *docVar) describe() []string {
	var out []string
	if d.meaning != "" {
		out = append(out, d.meaning)
	}
	if !d.hasDef && d.defCell != "" && d.defCell != "—" {
		out = append(out, "Default: "+d.defCell)
	}
	return out
}

// typeSchema maps a Go type to its schema.
func (g *schemaGen) typeSchema(t reflect.Type, path string, def reflect.Value) jsonObj {
	switch t {
	case reflect.TypeFor[time.Duration]():
		return jsonObj{"$ref": "#/$defs/duration"}
	case reflect.TypeFor[ByteSize]():
		return jsonObj{"$ref": "#/$defs/byteSize"}
	case reflect.TypeFor[IntList]():
		return jsonObj{"$ref": "#/$defs/intList"}
	case reflect.TypeFor[Tristate]():
		return jsonObj{"$ref": "#/$defs/tristate"}
	case reflect.TypeFor[VideoSecond]():
		return jsonObj{"$ref": "#/$defs/videoSecond"}
	case reflect.TypeFor[CIDR]():
		return jsonObj{"$ref": "#/$defs/cidr"}
	case reflect.TypeFor[Secret]():
		return jsonObj{"$ref": "#/$defs/secret"}
	case reflect.TypeFor[HexKey]():
		return jsonObj{"$ref": "#/$defs/hexKey"}
	case reflect.TypeFor[UnsignedPolicy]():
		return enumSchema(unsignedPolicies())
	case reflect.TypeFor[SourceType]():
		return enumSchema(sourceTypes())
	case reflect.TypeFor[LogLevel]():
		return enumSchema(logLevels())
	case reflect.TypeFor[Normalization]():
		return enumSchema(normalizations())
	case reflect.TypeFor[FailOn]():
		return enumSchema(failOns())
	case reflect.TypeFor[ToneMap]():
		return enumSchema(toneMaps())
	case reflect.TypeFor[AutoQualityMethod]():
		return enumSchema(autoQualityMethods())
	case reflect.TypeFor[StoreKind]():
		return enumSchema(storeKinds())
	case reflect.TypeFor[Format]():
		return enumSchema(append(formats(), formatJPGAlias))
	case reflect.TypeFor[DialectName]():
		return enumSchema(dialectNames())
	case reflect.TypeFor[[]MountOptions]():
		return jsonObj{"type": "array", "items": jsonObj{"$ref": "#/$defs/mount"}}
	}
	switch t.Kind() {
	case reflect.Bool:
		return jsonObj{"type": "boolean"}
	case reflect.Int, reflect.Int64:
		return jsonObj{"type": "integer"}
	case reflect.Float64:
		return jsonObj{"type": "number"}
	case reflect.String:
		return jsonObj{"type": "string"}
	case reflect.Slice:
		return jsonObj{"type": "array", "items": g.typeSchema(t.Elem(), path+"[]", reflect.Value{})}
	case reflect.Struct:
		return g.object(t, path, def)
	case reflect.Map:
		return g.mapSchema(t, path)
	default:
		panic(fmt.Sprintf("config schema: no mapping for %s (%s)", t, path))
	}
}

func (g *schemaGen) mapSchema(t reflect.Type, path string) jsonObj {
	switch {
	case path == "sources":
		return jsonObj{
			"type":                 "object",
			"additionalProperties": false,
			"patternProperties":    jsonObj{sourceNamePattern: jsonObj{"$ref": "#/$defs/source"}},
		}
	case path == "presets":
		return jsonObj{
			"type":                 "object",
			"additionalProperties": false,
			"patternProperties":    jsonObj{presetNamePattern: jsonObj{"type": "string", "minLength": 1}},
		}
	case t.Key() == reflect.TypeFor[Format]():
		props := jsonObj{}
		for _, f := range []string{string(FormatJPEG), formatJPGAlias, string(FormatWebP), string(FormatAVIF), string(FormatHEIC), string(FormatJXL)} {
			props[f] = g.typeSchema(t.Elem(), path+"."+f, reflect.Value{})
		}
		return jsonObj{"type": "object", "additionalProperties": false, "properties": props}
	default:
		return jsonObj{"type": "object", "additionalProperties": g.typeSchema(t.Elem(), path+".*", reflect.Value{})}
	}
}

func enumSchema[T ~string](values []T) jsonObj {
	out := make([]string, len(values))
	for i, v := range values {
		out[i] = string(v)
	}
	return jsonObj{"type": "string", "enum": out}
}

// containsSecret reports whether t is, or holds, a Secret or HexKey.
func containsSecret(t reflect.Type) bool {
	switch t {
	case reflect.TypeFor[Secret](), reflect.TypeFor[HexKey]():
		return true
	}
	switch t.Kind() {
	case reflect.Slice, reflect.Map:
		return containsSecret(t.Elem())
	default:
		return false
	}
}

// defaultValue renders a default in the file's own syntax. Nil lists and
// maps have no default (they mean "unset"), nor do structs.
func defaultValue(v reflect.Value) (any, bool) {
	switch x := v.Interface().(type) {
	case time.Duration:
		return x.String(), true
	case IntList:
		if x == nil {
			return nil, false
		}
		return []int(x), true
	case encoding.TextMarshaler:
		b, err := x.MarshalText()
		return string(b), err == nil
	}
	switch v.Kind() {
	case reflect.Bool:
		return v.Bool(), true
	case reflect.Int, reflect.Int64:
		return v.Int(), true
	case reflect.Float64:
		return v.Float(), true
	case reflect.String:
		return v.String(), true
	case reflect.Slice:
		if v.IsNil() {
			return nil, false
		}
		out := make([]any, 0, v.Len())
		for i := range v.Len() {
			e, ok := defaultValue(v.Index(i))
			if !ok {
				return nil, false
			}
			out = append(out, e)
		}
		return out, true
	case reflect.Map:
		if v.IsNil() {
			return nil, false
		}
		out := jsonObj{}
		for _, k := range v.MapKeys() {
			e, ok := defaultValue(v.MapIndex(k))
			if !ok {
				return nil, false
			}
			out[k.String()] = e
		}
		return out, true
	default:
		return nil, false
	}
}
